import{_ as a}from"./chunks/11b-settings-add-root.B9E5fG9m.js";import{_ as o}from"./chunks/09-login.BMTkVXpe.js";import{_ as t,o as r,c as i,a2 as n}from"./chunks/framework.D4up2k3b.js";const m=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"ops/faq.md","filePath":"ops/faq.md","lastUpdated":1791393728000}'),d={name:"ops/faq.md"};function c(l,e,s,h,f,p){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="侧栏没有-agent" tabindex="-1">侧栏没有 Agent？ <a class="header-anchor" href="#侧栏没有-agent" aria-label="Permalink to &quot;侧栏没有 Agent？&quot;">​</a></h2><p>按顺序排查：</p><ol><li>Agent 进程是否在跑：<code>ps</code> / systemd status。</li><li>能否解析 Hub 主机名：在 Agent 机 <code>curl -v https://filebox.example.com/api/health</code>。</li><li>Hub URL 是否为 <code>https://</code>（或开发时显式 <code>FILEBOX_ALLOW_INSECURE_HUB=1</code> + <code>ws://</code>）。</li><li>token 是否与 Hub <code>--init-config</code> 打印的一致（Hub 只存 hash，对不上只能重新发 / 重新配）。</li><li>反代是否正确升级 WebSocket（<code>Upgrade</code> / <code>Connection</code>），见 <a href="./hub">Hub 运维</a>。</li></ol><h2 id="有-agent-但文件列表空" tabindex="-1">有 Agent 但文件列表空？ <a class="header-anchor" href="#有-agent-但文件列表空" aria-label="Permalink to &quot;有 Agent 但文件列表空？&quot;">​</a></h2><p>需要在 <strong>Settings → Add Root</strong> 添加可读目录。无效路径会被拒绝且不破坏已有配置。见 <a href="/filebox/docs/guide/first-login">首次登录</a>。</p><p><img src="'+a+'" alt="Add Root"></p><h2 id="登录一直-solving-continue-灰掉" tabindex="-1">登录一直 Solving / Continue 灰掉？ <a class="header-anchor" href="#登录一直-solving-continue-灰掉" aria-label="Permalink to &quot;登录一直 Solving / Continue 灰掉？&quot;">​</a></h2><p>登录前必须完成 PoW（Verification → Ready）。若卡住：刷新 challenge、检查 <code>/api/pow/challenge</code> 是否可达、是否触发 IP 限流。见 <a href="/filebox/docs/guide/first-login">首次登录</a>。</p><p><img src="'+o+'" alt="登录 PoW"></p><h2 id="搜索很慢-被取消" tabindex="-1">搜索很慢 / 被取消？ <a class="header-anchor" href="#搜索很慢-被取消" aria-label="Permalink to &quot;搜索很慢 / 被取消？&quot;">​</a></h2><p>大树请收窄 root、加深忽略目录（如 <code>node_modules</code> / <code>venv</code>）、降低深度；可随时 Cancel。单 Agent 同时只跑一个搜索。见 <a href="/filebox/docs/features/search">搜索</a>。</p><h2 id="打不开某些文件" tabindex="-1">打不开某些文件？ <a class="header-anchor" href="#打不开某些文件" aria-label="Permalink to &quot;打不开某些文件？&quot;">​</a></h2><p>敏感路径（<code>.ssh/</code>、<code>.env*</code>、<code>*.pem</code> 等）默认拒绝，即使在已授权 root 内。见 <a href="/filebox/docs/features/security">安全与敏感文件</a>。</p><h2 id="office-预览灰掉-失败" tabindex="-1">Office 预览灰掉 / 失败？ <a class="header-anchor" href="#office-预览灰掉-失败" aria-label="Permalink to &quot;Office 预览灰掉 / 失败？&quot;">​</a></h2><p>Agent 上是否配置了可用的 <code>soffice</code>？见 <a href="./office">Office 预览</a>。无 LibreOffice 时仍可 Download。</p><h2 id="terminal-要验证码" tabindex="-1">Terminal 要验证码？ <a class="header-anchor" href="#terminal-要验证码" aria-label="Permalink to &quot;Terminal 要验证码？&quot;">​</a></h2><p>必须在 Agent 本机完成 <code>./agent --setup-terminal-2fa</code>（或设置 <code>FILEBOX_AGENT_TERMINAL_TOTP_SECRET</code>）并重启。Hub 不保存密钥。每次 Open / Resume 都要新码。见 <a href="/filebox/docs/features/terminal">远程终端</a>。</p><h2 id="transfer-找不到入口" tabindex="-1">Transfer 找不到入口？ <a class="header-anchor" href="#transfer-找不到入口" aria-label="Permalink to &quot;Transfer 找不到入口？&quot;">​</a></h2><p>侧栏仅在 Agent 声明 <code>temp_upload</code> 能力时显示 Transfer。当前发布版默认具备；若自定义构建关闭了该能力则不会出现。</p><h2 id="演示页和文档截图什么关系" tabindex="-1">演示页和文档截图什么关系？ <a class="header-anchor" href="#演示页和文档截图什么关系" aria-label="Permalink to &quot;演示页和文档截图什么关系？&quot;">​</a></h2><p><a href="https://zhimingye.github.io/filebox/" target="_blank" rel="noreferrer">在线演示</a> 是静态营销页，方便快速点点看布局。<strong>本用户文档站的截图全部来自真实运行的 Hub + Agent</strong>，与你部署后看到的界面一致（含登录 PoW、Search 浮窗、Settings、Audit、Terminal TOTP 等）。</p><h2 id="开发联调" tabindex="-1">开发联调？ <a class="header-anchor" href="#开发联调" aria-label="Permalink to &quot;开发联调？&quot;">​</a></h2><p>见仓库 <a href="https://github.com/ZhimingYe/filebox/blob/main/docs/local-debugging.md" target="_blank" rel="noreferrer"><code>docs/local-debugging.md</code></a>（<code>FILEBOX_DEV_MODE=1</code> 等）。仓库根目录 <code>docs/</code> 是开发者 runbook，<strong>不</strong>并入本用户文档站。</p>',24)])])}const _=t(d,[["render",c]]);export{m as __pageData,_ as default};
